64	    /**
65	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
66	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
67	     * stored lower-cased.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
