230	    /**
231	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
232	     * offending field is collected so the caller learns exactly which values must be supplied.
233	     *
234	     * @param ownerFieldsDto the submitted owner payload
235	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
236	     *         telephone is missing or blank
237	     */
238	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
239	        List<String> missingFields = new ArrayList<>();
240	        if (isBlank(ownerFieldsDto.getFirstName())) {
241	            missingFields.add("firstName");
242	        }
243	        if (isBlank(ownerFieldsDto.getLastName())) {
244	            missingFields.add("lastName");
245	        }
246	        if (isBlank(ownerFieldsDto.getAddress())) {
247	            missingFields.add("address");
248	        }
249	        if (isBlank(ownerFieldsDto.getCity())) {
250	            missingFields.add("city");
251	        }
252	        if (isBlank(ownerFieldsDto.getTelephone())) {
253	            missingFields.add("telephone");
254	        }
255	        if (!missingFields.isEmpty()) {
256	            throw new MissingOwnerFieldsException(missingFields);
257	        }
258	    }
259	
260	    private boolean isBlank(String value) {
261	        return value == null || value.isBlank();
262	    }
263	
264	    /**
265	     * Builds an owner's customer code, formatted '&lt;LAST3&gt;-&lt;NNNN&gt;'. LAST3 is the
266	     * upper-cased first three letters of the last name; NNNN is a global 4-digit zero-padded
267	     * sequence equal to one more than the current number of owners (e.g. 'SMI-0007').
268	     *
269	     * @param lastName the owner's last name
270	     * @return the formatted customer code
271	     */
272	    private String generateCustomerCode(String lastName) {
273	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
274	        int sequence = this.clinicService.findAllOwners().size() + 1;
275	        return String.format("%s-%04d", last3, sequence);
276	    }
277	
278	    /**
279	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
280	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
281	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
282	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
283	     * stored and returned.
284	     *
285	     * @param telephone the raw telephone value from the request
286	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
287	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
288	     */
289	    private String normalizeTelephone(String telephone) {
290	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
291	        String e164;
292	        if (cleaned.startsWith("+")) {
293	            e164 = cleaned;
294	        } else {
295	            String national = cleaned;
296	            if (national.startsWith("0")) {
297	                national = national.substring(1);
298	            }
299	            e164 = "+61" + national;
300	        }
301	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
302	            throw new InvalidOwnerFieldsException(List.of("telephone"));
303	        }
304	        return e164;
305	    }
306	
307	    /**
308	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
309	     * left unset. When a value is present it must be a syntactically valid address; the normalized
310	     * form stored and returned is the value lower-cased.
311	     *
312	     * @param email the raw email value from the request, or {@code null} when none was supplied
313	     * @return the lower-cased email, or {@code null} when no email was supplied
314	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
315	     */
316	    private String normalizeEmail(String email) {
317	        if (email == null || email.isBlank()) {
318	            return null;
319	        }
320	        if (!EMAIL_PATTERN.matcher(email).matches()) {
321	            throw new InvalidOwnerFieldsException(List.of("email"));
322	        }
323	        return email.toLowerCase(Locale.ROOT);
324	    }
325	
326	    /**
327	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
328	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
329	     * directly and is therefore independent of the punctuation a caller supplied.
330	     *
331	     * @param e164Telephone the E.164 telephone of the owner being created
332	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
333	     */
334	    private void rejectDuplicateTelephone(String e164Telephone) {
335	        boolean inUse = this.clinicService.findAllOwners().stream()
336	            .map(Owner::getTelephone)
337	            .filter(existing -> existing != null)
338	            .anyMatch(e164Telephone::equals);
339	        if (inUse) {
340	            throw new DuplicateOwnerTelephoneException(e164Telephone);
341	        }
342	    }
343	
344	    /**
345	     * Rejects an owner create that would form a second owner in an existing household - one whose
346	     * last name and address already belong to another owner. Last name and address are compared
347	     * case-insensitively after surrounding whitespace is trimmed and each internal run of whitespace
348	     * is collapsed to a single space, so purely cosmetic differences in spacing or letter case still
349	     * count as the same household. The check is skipped when the caller sets {@code sharesHousehold}
350	     * true to deliberately register a housemate.
351	     *
352	     * @param owner the owner being created
353	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
354	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and address
355	     */
356	    private void rejectDuplicateHousehold(Owner owner, Boolean sharesHousehold) {
357	        if (Boolean.TRUE.equals(sharesHousehold)) {
358	            return;
359	        }
360	        String lastName = normalizeHouseholdField(owner.getLastName());
361	        String address = normalizeHouseholdField(owner.getAddress());
362	        boolean clash = this.clinicService.findAllOwners().stream()
363	            .anyMatch(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
364	                && normalizeHouseholdField(existing.getAddress()).equals(address));
365	        if (clash) {
366	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
367	        }
368	    }
369	
370	    /**
371	     * Normalizes a last name or address for household comparison: surrounding whitespace is trimmed,
372	     * each internal run of whitespace is collapsed to a single space and the result is lower-cased.
373	     *
374	     * @param value the raw last name or address, or {@code null}
375	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
376	     */
377	    private String normalizeHouseholdField(String value) {
378	        if (value == null) {
379	            return "";
380	        }
381	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
382	    }
383	}
