132	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
133	     */
134	    @ExceptionHandler(MethodArgumentNotValidException.class)
135	    @ResponseBody
136	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
137	        HttpStatus status = HttpStatus.BAD_REQUEST;
138	        BindingErrorsResponse errors = new BindingErrorsResponse();
139	        BindingResult bindingResult = e.getBindingResult();
140	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
141	        if (bindingResult.hasErrors()) {
142	            errors.addAllErrors(bindingResult);
143	            List<String> missingFields = bindingResult.getFieldErrors().stream()
144	                .filter(fieldError -> {
145	                    Object rejected = fieldError.getRejectedValue();
146	                    return rejected == null || (rejected instanceof String value && value.isBlank());
147	                })
148	                .map(fieldError -> fieldError.getField())
149	                .distinct()
150	                .toList();
151	            detail.setProperty("errors", missingFields);
152	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
153	                .map(fieldError -> {
154	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
155	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
156	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
157	                        fieldError.getField(),
158	                        defaultMessage,
159	                        rejectedValue);
160	                    return new ValidationMessageDto(message)
161	                        .putAdditionalProperty("field", fieldError.getField())
162	                        .putAdditionalProperty("rejectedValue", rejectedValue)
163	                        .putAdditionalProperty("defaultMessage", defaultMessage);
164	                })
165	                .toList();
166	            logger.debug("Validation error at {} {}: {}",
167	                request.getMethod(),
168	                request.getRequestURI(),
169	                bindingResult.getFieldErrors());
170	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
171	            return ResponseEntity.status(status).body(detail);
172	        }
